import re

from markupsafe import Markup, escape

_PLACEHOLDER = re.compile(r"\{\{\s*(\w+)\s*\}\}")


def render(template, **context):
    def substitute(match):
        name = match.group(1)
        if name not in context:
            raise KeyError(name)
        return str(escape(str(context[name])))

    return Markup(_PLACEHOLDER.sub(substitute, template))
from markupsafe import Markup

from northdesk.render import render


def test_plain_substitution():
    assert render("Hello {{ name }}", name="Ada") == "Hello Ada"


def test_escapes_untrusted_text():
    assert render("<p>{{ name }}</p>", name="<b>x</b>") == "<p>&lt;b&gt;x&lt;/b&gt;</p>"


def test_markup_values_are_not_double_escaped():
    link = Markup('<a href="/reset">reset</a>')
    assert render("<p>{{ link }}</p>", link=link) == '<p><a href="/reset">reset</a></p>'


def test_unescaped_ampersand_in_markup():
    badge = Markup("Q&amp;A")
    assert render("{{ badge }}", badge=badge) == "Q&amp;A"


def test_missing_key():
    try:
        render("{{ nope }}")
    except KeyError as exc:
        assert exc.args == ("nope",)
    else:
        raise AssertionError("expected KeyError")

from .headers import format_subject
from .render import render


class Message:
    def __init__(self, subject, template, prefix=None):
        self.subject = format_subject(prefix, subject)
        self.template = template

    def body(self, **context):
        return render(self.template, **context)

    def as_dict(self, **context):
        return {"subject": self.subject, "html": str(self.body(**context))}
from markupsafe import Markup, escape


def money(cents, currency="USD"):
    sign = "-" if cents < 0 else ""
    whole, frac = divmod(abs(int(cents)), 100)
    return f"{sign}{whole:,}.{frac:02d} {currency}"


def truncate(value, length=40):
    text = str(value)
    if len(text) <= length:
        return escape(text)
    return escape(text[: length - 1]) + Markup("&hellip;")
